def contacts_search(query, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0447000" if __import__("os").path.isdir("./environment_mix/0447000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    audits = _load("audit_log.json")
    if not isinstance(audits, list):
        audits = []

    # Rate limit: max 60 calls per rolling 60 seconds (global, since auth is ambient)
    now = datetime.datetime.utcnow()
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for e in audits:
        ts = e.get("timestamp")
        if isinstance(ts, str):
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start:
                recent += 1
    if recent >= 60:
        audits.append({
            "event_id": "evt_" + now.strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "contacts_search",
            "status": "RATE_LIMIT",
            "timestamp": now.isoformat() + "Z",
            "latency_ms": 0
        })
        _save("audit_log.json", audits)
        return _err("RATE_LIMIT", "Rate limit exceeded. Please retry shortly.")

    # Validate
    if query is None or not isinstance(query, str):
        status = "VALIDATION_ERROR"
        out = _err("VALIDATION_ERROR", "query is required and must be a string.", field="query")
    else:
        q = query.strip()
        if q == "":
            status = "VALIDATION_ERROR"
            out = _err("VALIDATION_ERROR", "Search term is invalid.", field="query")
        else:
            contacts = _load("contacts.json")
            if not isinstance(contacts, list):
                contacts = []
            ql = q.lower()
            matches = []
            for c in contacts:
                if not isinstance(c, dict):
                    continue
                name = (c.get("name") or "")
                email = (c.get("email") or "")
                if isinstance(name, str) and ql in name.lower():
                    matches.append(c)
                elif isinstance(email, str) and ql in email.lower():
                    matches.append(c)
            status = "OK"
            out = {
                "data": matches,
                "meta": {"total": len(matches), "has_more": False, "next_cursor": None}
            }

    t1 = datetime.datetime.utcnow()
    audits.append({
        "event_id": "evt_" + t1.strftime("%Y%m%d%H%M%S%f"),
        "endpoint": "contacts_search",
        "status": status,
        "timestamp": t1.isoformat() + "Z",
        "latency_ms": int((t1 - t0).total_seconds() * 1000)
    })
    _save("audit_log.json", audits)
    return out

def contacts_send_message(contact_id, body, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0447000" if __import__("os").path.isdir("./environment_mix/0447000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    audits = _load("audit_log.json")
    if not isinstance(audits, list):
        audits = []

    # Rate limit: max 60 calls per rolling 60 seconds (global)
    now = datetime.datetime.utcnow()
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for e in audits:
        ts = e.get("timestamp")
        if isinstance(ts, str):
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start:
                recent += 1
    if recent >= 60:
        audits.append({
            "event_id": "evt_" + now.strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "contacts_send_message",
            "status": "RATE_LIMIT",
            "timestamp": now.isoformat() + "Z",
            "latency_ms": 0
        })
        _save("audit_log.json", audits)
        return _err("RATE_LIMIT", "Rate limit exceeded. Please retry shortly.")

    # Validate inputs
    if contact_id is None or not isinstance(contact_id, str) or contact_id.strip() == "":
        status = "VALIDATION_ERROR"
        out = _err("VALIDATION_ERROR", "contact_id is required and must be a non-empty string.", field="contact_id")
    elif body is None or not isinstance(body, str) or body.strip() == "":
        status = "VALIDATION_ERROR"
        out = _err("VALIDATION_ERROR", "body is required and must be a non-empty string.", field="body")
    else:
        cid = contact_id.strip()
        contacts = _load("contacts.json")
        if not isinstance(contacts, list):
            contacts = []
        recipient = None
        for c in contacts:
            if isinstance(c, dict) and c.get("contact_id") == cid:
                recipient = c
                break

        if recipient is None:
            status = "NOT_FOUND"
            out = _err("NOT_FOUND", "Recipient contact_id does not exist.", contact_id=cid)
        else:
            # Persist message to messages.json (created if missing)
            messages = _load("messages.json")
            if not isinstance(messages, list):
                messages = []

            # Id generation
            ts = datetime.datetime.utcnow()
            msg_id = "msg_" + ts.strftime("%Y%m%d%H%M%S%f")
            existing_ids = {m.get("message_id") for m in messages if isinstance(m, dict)}
            while msg_id in existing_ids:
                ts = datetime.datetime.utcnow()
                msg_id = "msg_" + ts.strftime("%Y%m%d%H%M%S%f")

            msg = {
                "message_id": msg_id,
                "from_contact_id": None,
                "to_contact_id": cid,
                "body": body,
                "status": "queued",
                "queued_at": ts.isoformat() + "Z"
            }
            messages.append(msg)
            _save("messages.json", messages)

            status = "OK"
            out = {
                "data": {
                    "message_id": msg_id,
                    "status": "queued",
                    "to": cid,
                    "recipient_email": recipient.get("email"),
                    "body": body,
                    "queued_at": msg["queued_at"]
                }
            }

    t1 = datetime.datetime.utcnow()
    audits.append({
        "event_id": "evt_" + t1.strftime("%Y%m%d%H%M%S%f"),
        "endpoint": "contacts_send_message",
        "status": status,
        "timestamp": t1.isoformat() + "Z",
        "latency_ms": int((t1 - t0).total_seconds() * 1000)
    })
    _save("audit_log.json", audits)
    return out

