def get_message_history(contact_id=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0447000" if __import__("os").path.isdir("./environment_mix/0447000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    audits = _load("audit_log.json")
    if not isinstance(audits, list):
        audits = []

    # Rate limit: max 60 calls per rolling 60 seconds (global)
    now = datetime.datetime.utcnow()
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for e in audits:
        ts = e.get("timestamp")
        if isinstance(ts, str):
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start:
                recent += 1
    if recent >= 60:
        audits.append({
            "event_id": "evt_" + now.strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "get_message_history",
            "status": "RATE_LIMIT",
            "timestamp": now.isoformat() + "Z",
            "latency_ms": 0
        })
        _save("audit_log.json", audits)
        return _err("RATE_LIMIT", "Rate limit exceeded. Please retry shortly.")

    # Validate optional filter
    if contact_id is not None:
        if (not isinstance(contact_id, str)) or contact_id.strip() == "":
            status = "VALIDATION_ERROR"
            out = _err("VALIDATION_ERROR", "contact_id must be a non-empty string when provided.", field="contact_id")
        else:
            cid = contact_id.strip()
            contacts = _load("contacts.json")
            if not isinstance(contacts, list):
                contacts = []
            exists = any(isinstance(c, dict) and c.get("contact_id") == cid for c in contacts)
            if not exists:
                status = "NOT_FOUND"
                out = _err("NOT_FOUND", "contact_id does not exist.", contact_id=cid)
            else:
                messages = _load("messages.json")
                if not isinstance(messages, list):
                    messages = []
                filtered = []
                for m in messages:
                    if not isinstance(m, dict):
                        continue
                    if m.get("from_contact_id") == cid or m.get("to_contact_id") == cid:
                        filtered.append(m)
                status = "OK"
                out = {
                    "data": filtered,
                    "meta": {"total": len(filtered), "has_more": False, "next_cursor": None}
                }
    else:
        messages = _load("messages.json")
        if not isinstance(messages, list):
            messages = []
        status = "OK"
        out = {
            "data": [m for m in messages if isinstance(m, dict)],
            "meta": {"total": len([m for m in messages if isinstance(m, dict)]), "has_more": False, "next_cursor": None}
        }

    t1 = datetime.datetime.utcnow()
    audits.append({
        "event_id": "evt_" + t1.strftime("%Y%m%d%H%M%S%f"),
        "endpoint": "get_message_history",
        "status": status,
        "timestamp": t1.isoformat() + "Z",
        "latency_ms": int((t1 - t0).total_seconds() * 1000)
    })
    _save("audit_log.json", audits)
    return out
